const languageName: string = "TypeScript";
const releaseYear: number = 2012;
const isStaticallyTyped: boolean = true;

console.log(`Language: ${languageName}`);
console.log(`Year: ${releaseYear}`);
console.log(`Static Typing: ${isStaticallyTyped}`);

// TypeScript infers 'count' as type number based on initial assignment
let count = 42;

// Valid reassignment with the same inferred type
count = 100;

// INVALID: TypeScript produces a compile-time type error:
// Error: Type 'string' is not assignable to type 'number'.
// count = "one hundred";

// 'any' turns off TypeScript type checking entirely (dangerous!)
let looseValue: any = "hello";
looseValue.nonExistentMethod(); // Compiles without error, but crashes at runtime!

// 'unknown' is the type-safe counterpart of any
let strictValue: unknown = "hello world";

// strictValue.toUpperCase(); // Error: Object is of type 'unknown'.

// Must narrow type via type check before usage:
if (typeof strictValue === "string") {
  console.log(strictValue.toUpperCase()); // Safe and allowed!
}

// 1. Number array
const scores: Array<number> = [95, 88, 76, 100];
// Alternatively: const scores: number[] = [95, 88, 76, 100];

// 2. Fixed-length Tuple: [number, string]
let httpResponse: [number, string] = [200, "OK"];

// Updating tuple with correct types in fixed positions
httpResponse = [404, "Not Found"];

console.log(`Status: ${httpResponse[0]}, Message: ${httpResponse[1]}`);

function formatUsername(name: string | null): string {
  // When strictNullChecks is true, null cannot be treated as a string
  if (name === null) {
    return "Anonymous User";
  }

  // Inside this block, TypeScript automatically narrows 'name' to string
  return name.trim().toUpperCase();
}

console.log(formatUsername("alice")); // ALICE
console.log(formatUsername(null));    // Anonymous User

// document.getElementById returns HTMLElement | null
// We assert the specific subtype HTMLInputElement using 'as'
const inputElement = document.getElementById("user-email") as HTMLInputElement;

// Now we can safely access HTMLInputElement properties like .value
if (inputElement) {
  inputElement.value = "student@example.com";
  console.log("Input value:", inputElement.value);
}

// CAUTION: Type assertions tell the compiler 'trust me, I know the type'.
// Avoid assertions when type narrowing (e.g. instanceof) can guarantee safety instead.
